<?php
namespace App\Http\Controllers\Api\HrV2;use App\Http\Controllers\Controller;use App\Models\HrRoster;use Illuminate\Http\Request;
class RosterController extends Controller{public function index(Request $r){$q=HrRoster::with(['employee:id,employee_number,first_name,last_name','shift:id,code,name,start_time,end_time']);if($r->from)$q->whereDate('work_date','>=',$r->from);if($r->to)$q->whereDate('work_date','<=',$r->to);return response()->json($q->orderBy('work_date')->paginate($r->integer('per_page',100)));}public function store(Request $r){$d=$this->data($r);return response()->json(HrRoster::updateOrCreate(['employee_id'=>$d['employee_id'],'work_date'=>$d['work_date']],$d),201);}public function update(Request $r,HrRoster $roster){$d=$this->data($r,true);$roster->update($d);return response()->json($roster->fresh(['employee','shift']));}public function destroy(HrRoster $roster){$roster->delete();return response()->json(['success'=>true]);}private function data(Request $r,bool $partial=false):array{$p=$partial?'sometimes':'required';return $r->validate(['employee_id'=>[$p,'exists:hr_employees,id'],'shift_id'=>'nullable|exists:hr_shifts,id','work_date'=>[$p,'date'],'planned_start'=>'nullable','planned_end'=>'nullable','status'=>[$p,'in:scheduled,day_off,leave,holiday,cancelled'],'notes'=>'nullable|string']);}}